// Check every Approved row before it reaches sprkly.
// A row that fails gets Status "Error" and a plain reason.
// A time with no zone is read in this workflow's time zone (Workflow settings).
const zone = (typeof $now !== 'undefined' && $now && $now.zoneName) || 'UTC';
const nowMs = Date.now();

function zoneOffset(ms) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: zone, hourCycle: 'h23', year: 'numeric', month: '2-digit', day: '2-digit',
    hour: '2-digit', minute: '2-digit', second: '2-digit',
  }).formatToParts(new Date(ms));
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  const wall = Date.UTC(get('year'), get('month') - 1, get('day'), get('hour'), get('minute'), get('second'));
  return wall - Math.floor(ms / 1000) * 1000;
}

// "2026-12-01 09:00", "2026-12-01 9:00:00", "2026-12-01T09:00" or a time with Z or +08:00.
function toIso(text) {
  if (/T\d{1,2}:\d{2}(:\d{2})?(\.\d+)?([zZ]|[+-]\d{2}:?\d{2})$/.test(text)) {
    const date = new Date(text);
    return Number.isNaN(date.getTime()) ? null : date.toISOString();
  }
  const m = text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})[T ](\d{1,2}):(\d{2})(?::(\d{2}))?$/);
  if (!m) return null;
  const [y, mo, d, h, mi, s] = [m[1], m[2], m[3], m[4], m[5], m[6] || '0'].map(Number);
  const wall = Date.UTC(y, mo - 1, d, h, mi, s);
  const check = new Date(wall);
  if (h > 23 || mi > 59 || s > 59 || check.getUTCMonth() !== mo - 1 || check.getUTCDate() !== d) return null;
  const firstGuess = wall - zoneOffset(wall);
  return new Date(wall - zoneOffset(firstGuess)).toISOString();
}

const out = [];
for (const item of $input.all()) {
  const row = item.json;
  const fail = (reason) => out.push({ json: { row_number: row.row_number, valid: false, Status: 'Error', Error: reason } });
  const rowId = String(row['Row ID'] ?? '').trim();
  const caption = String(row['Caption'] ?? '').trim();
  const timeText = String(row['Schedule Time'] ?? '').trim();
  const accounts = String(row['Accounts'] ?? '').split(/[,\n]/).map((s) => s.trim()).filter(Boolean);
  const mediaUrls = String(row['Media URL'] ?? '').split(/[\s,]+/).filter(Boolean);

  if (!rowId) { fail('Row ID is empty. Give each row its own ID, like 1, 2, 3.'); continue; }
  if (rowId.includes(':')) { fail('Row ID cannot have a colon in it.'); continue; }
  if (!caption) { fail('Caption is empty.'); continue; }
  // The sprkly API posts right away when there is no time. This workflow never does.
  if (!timeText) { fail('Schedule Time is empty. This workflow never posts right away. Add a time like 2026-12-01 09:00.'); continue; }
  const scheduledTime = toIso(timeText);
  if (!scheduledTime) { fail('Schedule Time "' + timeText + '" is not a time. Use a time like 2026-12-01 09:00.'); continue; }
  if (Date.parse(scheduledTime) <= nowMs) { fail('Schedule Time is in the past. Pick a time that has not come yet.'); continue; }
  if (accounts.length === 0) { fail('Accounts is empty. Add one, like instagram:myhandle.'); continue; }
  const badUrl = mediaUrls.find((url) => !/^https?:\/\//i.test(url));
  if (badUrl) { fail('Media URL "' + badUrl + '" is not a web link. It must start with https://'); continue; }

  out.push({ json: { row_number: row.row_number, valid: true, rowId, caption, scheduledTime, accounts, mediaUrls: mediaUrls.join(',') } });
}
return out;

// One account list per run, from "Get sprkly accounts once", matched to every row.
// Each account in a row is platform:handle, like instagram:myhandle or telegram:My channel.
const res = $input.first().json;
const body = res.body && typeof res.body === 'object' ? res.body : {};
const accounts = res.statusCode === 200 && Array.isArray(body.accounts) ? body.accounts.filter((a) => a && a.id) : null;
const apiProblem = accounts ? '' : 'sprkly did not send your accounts: ' +
  (body.error || res.error || 'no answer') + (res.statusCode ? ' (HTTP ' + res.statusCode + ')' : '');
const norm = (value) => String(value ?? '').trim().replace(/^@/, '').toLowerCase();

const out = [];
for (const { json: row } of $('Check each row').all()) {
  if (!row.valid) {
    out.push({ json: { row_number: row.row_number, ready: false, Status: row.Status, Error: row.Error } });
    continue;
  }
  const ids = [];
  let problem = apiProblem;
  for (const ref of problem ? [] : row.accounts) {
    const cut = ref.indexOf(':');
    if (cut < 1) { problem = '"' + ref + '" is not platform:handle. Write it like instagram:myhandle.'; break; }
    const platform = norm(ref.slice(0, cut));
    const handle = norm(ref.slice(cut + 1));
    const match = accounts.find((account) => norm(account.platform) === platform && norm(account.handle) === handle);
    if (!match) { problem = 'No connected sprkly account is ' + ref + '. Check the platform and the name in sprkly.'; break; }
    if (!ids.includes(String(match.id))) ids.push(String(match.id));
  }
  // A row only goes on with a time. The sprkly API posts right away when there is none.
  if (!problem && !row.scheduledTime) problem = 'Schedule Time is empty. This workflow never posts right away.';
  if (problem) {
    out.push({ json: { row_number: row.row_number, ready: false, Status: 'Error', Error: problem } });
    continue;
  }
  const request = { profileIds: ids, caption: row.caption, scheduledTime: row.scheduledTime, externalId: 'sheet-' + row.rowId };
  if (row.mediaUrls) request.mediaUrls = row.mediaUrls.split(',');
  out.push({ json: { row_number: row.row_number, ready: true, rowId: row.rowId, scheduledTime: row.scheduledTime, request } });
}
return out;

// sprkly answers once per row sent, in the same order. Turn each answer into the row's new Status.
// The request node keeps the status code and body (Include Response Headers and Status, Never Error).
const sent = $('Match accounts to rows').all().filter((item) => item.json.ready);
const label = { scheduled: 'Scheduled', pending_approval: 'Scheduled', draft: 'Scheduled', posted: 'Published', published: 'Published', failed: 'Failed' };

return $input.all().map((item, index) => {
  const res = item.json;
  const body = res.body && typeof res.body === 'object' ? res.body : {};
  const row = (sent[index] && sent[index].json) || {};
  const base = { row_number: row.row_number };

  if ((res.statusCode === 201 || res.statusCode === 200) && Array.isArray(body.postIds)) {
    return { json: { ...base, Status: label[body.status] || 'Scheduled', 'sprkly Post ID': body.postIds.join(', '),
      'Scheduled For': body.scheduledTime || row.scheduledTime, Error: '' } };
  }

  // Same External ID as an earlier post: nothing new was posted. Keep the first post's ID and status.
  // The 409 body has no time, so write the time this row asked for.
  if (res.statusCode === 409 && body.code === 'duplicate_external_id') {
    return { json: { ...base, Status: label[body.existingStatus] || 'Scheduled', 'sprkly Post ID': body.existingPostId || '',
      'Scheduled For': row.scheduledTime || '', Error: '' } };
  }

  const reason = body.error || res.error || (typeof res.data === 'string' && res.data.slice(0, 200)) || 'sprkly gave no reason.';
  const tag = res.statusCode ? ' (HTTP ' + res.statusCode + (body.code ? ', ' + body.code : '') + ')' : '';
  return { json: { ...base, Status: 'Error', Error: reason + tag } };
});

// Where the last run stopped. Kept in this workflow's static data, which n8n saves
// only for runs of the active workflow (not for manual test runs).
// First run: start from now, so posts from before you turned it on are not replayed.
const data = $getWorkflowStaticData('global');
if (!data.sprklyCursor) {
  data.sprklyCursor = new Date().toISOString();
  data.sprklyHandled = [];
  return [];
}
return [{ json: { updatedAfter: data.sprklyCursor } }];

// Posts changed since the cursor, oldest change first. The External ID is sheet-<Row ID>.
// With several accounts sprkly adds :platform:account to it, so take the part before the first colon.
// Posts made outside this sheet, deleted posts and posts already handled are skipped.
// The request node keeps the status code (Include Response Headers and Status, Never Error).
// No good answer (a bad key, sprkly down): write nothing and keep the cursor, so the next run tries again.
const res = $input.first().json;
if (!res || res.statusCode !== 200 || !res.body || typeof res.body !== 'object') return [];
const data = $getWorkflowStaticData('global');
const posts = Array.isArray(res.body.posts) ? res.body.posts : [];
const handled = Array.isArray(data.sprklyHandled) ? data.sprklyHandled : [];
const seen = new Set(handled);
let cursor = data.sprklyCursor;

// One row can have several accounts, so one post each. Group them: one result per row.
const rows = new Map();
for (const post of posts) {
  // Move the cursor to the newest change seen, never past it. A full page (100) means
  // more are waiting: the next run starts from here.
  if (post.updatedAt && !Number.isNaN(Date.parse(post.updatedAt)) && (!cursor || Date.parse(post.updatedAt) > Date.parse(cursor))) {
    cursor = post.updatedAt;
  }
  if (post.deleted) continue;
  const found = String(post.externalId ?? '').match(/^sheet-([^:]+)(?::([^:]+))?/);
  if (!found) continue;
  const wentOut = post.status === 'posted' || post.status === 'published';
  if (!wentOut && post.status !== 'failed') continue;
  if (seen.has(post.id)) continue;
  seen.add(post.id);
  handled.push(post.id);
  if (!rows.has(found[1])) rows.set(found[1], { links: [], errors: [] });
  const row = rows.get(found[1]);
  if (wentOut) {
    if (post.permalink) row.links.push(post.permalink);
  } else {
    const platform = (Array.isArray(post.platforms) && post.platforms.join(', ')) || found[2] || 'post';
    row.errors.push(platform + ': ' + (post.failedReason || 'sprkly did not give a reason.'));
  }
}
data.sprklyCursor = cursor;
data.sprklyHandled = handled.slice(-500);

// Failed if any account failed, else Published. Every link goes in, with a space between.
return [...rows].map(([rowId, row]) => ({ json: {
  'Row ID': rowId,
  Status: row.errors.length ? 'Failed' : 'Published',
  Link: row.links.join(' '),
  Error: row.errors.join('; '),
} }));
